<script setup>
import { computed, onMounted, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { getAgent, getAgents, updateAgentPrompt, updateAgentStatus } from '../services/agentManagementApi'
const agents = ref([]), loading = ref(false), error = ref(''), drawerOpen = ref(false), detail = ref(null), detailLoading = ref(false), editing = ref(false), prompt = ref(''), version = ref('')
const stats = computed(() => ({ total: agents.value.length, active: agents.value.filter(a => a.status === 'active').length, inactive: agents.value.filter(a => a.status === 'inactive').length }))
onMounted(loadAgents)
async function loadAgents() { loading.value = true; error.value = ''; try { agents.value = await getAgents() } catch (e) { error.value = e.message } finally { loading.value = false } }
async function openAgent(row) { drawerOpen.value = true; detailLoading.value = true; detail.value = null; editing.value = false; try { detail.value = await getAgent(row.agent_name); prompt.value = detail.value.prompt; version.value = detail.value.version } catch (e) { ElMessage.error(e.message) } finally { detailLoading.value = false } }
async function toggleStatus(row) { const next = row.status === 'active' ? 'inactive' : 'active'; try { const updated = await updateAgentStatus(row.agent_name, next); Object.assign(row, updated); if (detail.value?.agent_name === row.agent_name) detail.value.status = updated.status; ElMessage.success(`Agent 已${next === 'active' ? '启用' : '停用'}`) } catch (e) { ElMessage.error(e.message) } }
async function savePrompt() { if (!detail.value || !prompt.value.trim()) return; try { detail.value = await updateAgentPrompt(detail.value.agent_name, prompt.value.trim(), version.value); const row = agents.value.find(a => a.agent_name === detail.value.agent_name); if (row) Object.assign(row, { version: detail.value.version, updated_time: detail.value.updated_time }); editing.value = false; ElMessage.success('已创建新的 Prompt 版本') } catch (e) { ElMessage.error(e.message) } }
function nextVersion() { version.value = `v${Number((detail.value?.version || 'v0').replace('v', '')) + 1}` }
function formatTime(value) { return value ? new Intl.DateTimeFormat('zh-CN', { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' }).format(new Date(value)) : '-' }
function tagType(status) { return status === 'active' ? 'success' : 'info' }
</script>
<template><section class="agent-management-page"><div class="agent-management-head"><div><span class="section-kicker">AGENT / CONFIGURATION CENTER</span><h2>Agent Management</h2><p>管理 Agent 状态、Prompt 版本及其绑定的工具和知识资产；本页配置不会改变当前运行链路。</p></div><el-button type="primary" :loading="loading" @click="loadAgents">刷新</el-button></div><div class="agent-management-stats"><article><span>Agents</span><strong>{{ stats.total }}</strong></article><article><span>Active</span><strong>{{ stats.active }}</strong></article><article><span>Inactive</span><strong>{{ stats.inactive }}</strong></article></div><section class="agent-management-table"><el-alert v-if="error" type="error" :closable="false" :title="error"/><el-table v-else v-loading="loading" :data="agents" height="calc(100vh - 330px)" @row-click="openAgent"><el-table-column prop="agent_name" label="Agent 名称" min-width="190"/><el-table-column prop="type" label="类型" width="130"/><el-table-column label="状态" width="115"><template #default="{ row }"><el-tag size="small" :type="tagType(row.status)">{{ row.status }}</el-tag></template></el-table-column><el-table-column prop="version" label="版本" width="90"/><el-table-column label="更新时间" min-width="175"><template #default="{ row }">{{ formatTime(row.updated_time) }}</template></el-table-column><el-table-column label="操作" width="175"><template #default="{ row }"><el-button link type="primary" @click.stop="openAgent(row)">详情</el-button><el-button link :type="row.status === 'active' ? 'danger' : 'success'" @click.stop="toggleStatus(row)">{{ row.status === 'active' ? '停用' : '启用' }}</el-button></template></el-table-column></el-table></section><el-drawer v-model="drawerOpen" :title="detail ? `${detail.agent_name} · Agent Detail` : 'Agent Detail'" size="650px" append-to-body><div class="agent-management-drawer" v-loading="detailLoading"><template v-if="detail"><section><h3>基础信息</h3><dl><div><dt>类型</dt><dd>{{ detail.type }}</dd></div><div><dt>状态</dt><dd><el-tag size="small" :type="tagType(detail.status)">{{ detail.status }}</el-tag></dd></div><div><dt>当前版本</dt><dd>{{ detail.version }}</dd></div><div><dt>更新时间</dt><dd>{{ formatTime(detail.updated_time) }}</dd></div></dl><p class="agent-description">{{ detail.description }}</p></section><section><div class="agent-section-heading"><h3>Prompt</h3><el-button v-if="!editing" size="small" type="primary" plain @click="editing = true; nextVersion()">创建新版本</el-button></div><template v-if="editing"><el-input v-model="version" class="prompt-version-input" placeholder="v2"/><el-input v-model="prompt" type="textarea" :rows="8"/><div class="agent-form-actions"><el-button @click="editing = false; prompt = detail.prompt; version = detail.version">取消</el-button><el-button type="primary" @click="savePrompt">保存版本</el-button></div></template><pre v-else>{{ detail.prompt }}</pre></section><section><h3>绑定知识库</h3><div class="agent-chip-list"><el-tag v-for="item in detail.knowledge_binding" :key="item" type="success">{{ item }}</el-tag><span v-if="!detail.knowledge_binding.length">未绑定知识库</span></div></section><section><h3>绑定工具</h3><div class="agent-chip-list"><el-tag v-for="item in detail.tools" :key="item" type="primary">{{ item }}</el-tag><span v-if="!detail.tools.length">未绑定工具</span></div></section><section><h3>Prompt 版本历史</h3><div class="agent-version-list"><article v-for="item in detail.prompt_versions" :key="item.version"><div><strong>{{ item.version }}</strong><span>{{ formatTime(item.created_time) }}</span></div><p>{{ item.prompt }}</p></article></div></section></template></div></el-drawer></section></template>
